JSONParser.swift:stringRunBody.code:
@inlinable
  @inline(__always)
  mutating func stringRunBody<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    from: Int,
    to: Int,
    run: StreamStringRun,
    into sink: inout Sink
  ) throws(JSONParsingError) -> Int {
    var i = from
    let end = run.end

    if end > i {
      if self.highSurrogate != 0 { throw self.loneHighSurrogateError(reportAt: i) }
      let emitEnd = end == to ? try self.trimmingIncompleteUTF8(base: base, from: i, to: end) : end
      if emitEnd > i {
        try self.validateUTF8IfNeeded(
          base: base,
          from: i,
          to: emitEnd,
          containsNonASCII: run.containsNonASCII,
          reportAt: nil
        )
        try self.record(.stringChunk, start: i, length: emitEnd &- i, end: emitEnd, base: base, into: &sink)
      }
      if emitEnd < end {
        try self.holdPendingUTF8(base: base, from: emitEnd, to: end)
      }
      i = end
    }

    guard i < to else { return i }

    let byte = base.load(fromByteOffset: i, as: UInt8.self)
    let byteAt = i
    i &+= 1
    if byte == .asciiQuote {
      if self.highSurrogate != 0 { throw self.loneHighSurrogateError(reportAt: byteAt) }
      try self.record(.stringEnd, start: byteAt, length: 1, end: i, base: base, into: &sink)
      self.state = .afterValue
      return try self.fuseAfterValue(base: base, from: i, to: to, into: &sink)
    } else if byte == .asciiBackslash {
      // The rest of this value is taken coalesced, out of line: the decode, the surrogate handling
      // and the buffer bookkeeping all leave this function, which cannot afford to grow. A
      // backslash that is the chunk's last byte cannot fuse and is answered here -- measured: the
      // call cost `Twitter escaped - byte by byte` -1.6%. Nothing is buffered yet on this edge.
      guard i < to else {
        self.state = .escape
        return i
      }
      return try self.coalescedEscapedStringTail(base: base, from: i, to: to, into: &sink)
    } else {
      throw self.error(.unterminatedString, at: byteAt)
    }
  }

JSONParser.swift:structuralRun.code:
@_transparent
  @usableFromInline
  mutating func structuralRun<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    from: Int,
    to: Int,
    blocks: Bool,
    into sink: inout Sink
  ) throws(JSONParsingError) -> Int {
    var i = from
    var state = self.state
    var depth = self.depth
    var containers = self.containers
    defer {
      self.state = state
      self.depth = depth
      self.containers = containers
    }
    while i < to {
      #if arch(arm64) || arch(x86_64)
        // The 64-byte block path (JSONParserBlocks.swift), tried at every token boundary because
        // that is where it is re-entered: anything it will not judge comes back here, and the
        // next block is available once this loop settles that token. `state.isStructural` is not
        // tested -- the loop only reaches its own top in a structural state.
        if blocks, i &+ 64 <= to {
          // Copies scoped to this branch, not the run's own locals: taking the address of `depth`
          // and `containers` makes `var depth = self.depth` address-taken, and the store it
          // becomes lands in the entry block, on every byte-fed call that never gets here.
          var blockState = state
          var blockDepth = depth
          var blockContainers = containers
          defer {
            state = blockState
            depth = blockDepth
            containers = blockContainers
          }
          i = try self.consumeStructuralBlocks(
            base: base, from: i, to: to, state: &blockState, depth: &blockDepth,
            containers: &blockContainers, into: &sink
          )
          // A negative answer is the walk giving up on this payload's shape (the gate in
          // JSONParserBlocks.swift); the index is its bitwise complement. Breaking honours it
          // without the loop holding anything mutable -- the dispatcher re-enters at once.
          if i < 0 {
            i = ~i
            break
          }
          // A block that handed the parse to the skip scanner, the string loop or the number path
          // leaves the run exactly as the step below would have.
          if !blockState.isStructural { break }
        }
      #endif
      // The scan hands back the byte it stopped on, so the dispatch below reads a register instead
      // of reloading the address the scan's one-compare fast path just tested.
      let scanned = streamWhitespaceEndByte(base: base, from: i, to: to)
      i = scanned.end
      if i == to { break }
      let byte = scanned.byte
      i &+= 1
      // A number is the one token whose first byte belongs to the token itself, so the run ends
      // and the byte is handed back for `.number` to re-read.
      if try self.consumeStructural(
        byte, base: base, cursor: &i, to: to, state: &state, depth: &depth,
        containers: &containers, into: &sink
      ) {
        i &-= 1
        break
      }
      if !state.isStructural { break }
    }
    return i
  }

JSONParser.swift:topIsObject.code:
@inlinable
  @inline(__always)
  var topIsObject: Bool {
    Self.topIsObject(depth: self.depth, containers: self.containers)
  }

@inlinable
  @inline(__always)
  static func topIsObject(depth: Int, containers: UInt64) -> Bool {
    depth > 0 && (containers &>> UInt64(depth &- 1)) & 1 == 1
  }

JSONParser.swift:trimmingIncompleteUTF8.code:
@inlinable
  @inline(__always)
  mutating func trimmingIncompleteUTF8(
    base: UnsafeRawPointer, from: Int, to: Int
  ) throws(JSONParsingError) -> Int {
    var index = to &- 1
    let lowest = Swift.max(from, to &- 4)
    while index >= lowest {
      let byte = base.load(fromByteOffset: index, as: UInt8.self)
      if byte < .utf8ContinuationFloor { return to }
      if byte >= .utf8TwoByteFloor {
        let needed = Self.sequenceLength(byte)
        let available = to &- index
        return available >= needed ? to : index
      }
      index &-= 1
    }
    return to
  }

JSONParser.swift:unicodeEscapeEnd.code:
@inlinable
  @inline(__always)
  mutating func unicodeEscapeEnd<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer, from: Int, to: Int, coalescing: Bool, into sink: inout Sink
  ) throws(JSONParsingError) -> Int? {
    guard from &+ 5 <= to, let scalar = streamHexQuad(base: base, from: from &+ 1) else {
      return nil
    }
    var value = scalar
    var end = from &+ 5

    if scalar >= .highSurrogateFloor, scalar <= .highSurrogateCeiling {
      // A pair is twelve bytes and must be complete and well formed to fuse; anything else is a
      // diagnostic for the per-byte path. The bounds test is first, so the load stays in the chunk.
      guard end &+ 6 <= to,
        UInt16(littleEndian: base.loadUnaligned(fromByteOffset: end, as: UInt16.self))
          == streamUnicodeEscapePrefix,
        let low = streamHexQuad(base: base, from: end &+ 2),
        low >= .lowSurrogateFloor, low <= .lowSurrogateCeiling
      else {
        return nil
      }
      value =
        .utf8ThreeByteCeiling &+ ((scalar &- .highSurrogateFloor) << 10)
        &+ (low &- .lowSurrogateFloor)
      end &+= 6
    } else if scalar >= .lowSurrogateFloor, scalar <= .lowSurrogateCeiling {
      // A lone low surrogate is a diagnostic, so it goes to the per-byte path.
      return nil
    }

    if coalescing {
      // A flush here delivers everything buffered ahead of this escape, so it reports one past
      // that chunk's last content byte: the backslash, `from &- 1` (as `bufferStringRun` does).
      let encoded = Self.utf8Word(value)
      try self.bufferStringScratch(encoded.word, count: encoded.count, into: &sink, reportAt: from &- 1)
    } else {
      // `emitScratch` reports at `reportAt &+ 1`, so `reportAt` must be the escape's *last* byte
      // -- `end &- 1` for a single escape and a surrogate pair alike; `from` reported 4 (10) early.
      try self.emitScalar(value, into: &sink, reportAt: end &- 1)
    }
    return end
  }

JSONParser.swift:utf8Word.code:
@inlinable
  @inline(__always)
  static func utf8Word(_ value: UInt32) -> (word: UInt64, count: Int) {
    let word: UInt64
    let count: Int
    if value < .utf8OneByteCeiling {
      word = UInt64(value)
      count = 1
    } else if value < .utf8TwoByteCeiling {
      word =
        UInt64(0xC0 | (value >> 6))
        | (UInt64(0x80 | (value & .utf8ContinuationMask)) &<< 8)
      count = 2
    } else if value < .utf8ThreeByteCeiling {
      word =
        UInt64(0xE0 | (value >> 12))
        | (UInt64(0x80 | ((value >> 6) & .utf8ContinuationMask)) &<< 8)
        | (UInt64(0x80 | (value & .utf8ContinuationMask)) &<< 16)
      count = 3
    } else {
      word =
        UInt64(0xF0 | (value >> 18))
        | (UInt64(0x80 | ((value >> 12) & .utf8ContinuationMask)) &<< 8)
        | (UInt64(0x80 | ((value >> 6) & .utf8ContinuationMask)) &<< 16)
        | (UInt64(0x80 | (value & .utf8ContinuationMask)) &<< 24)
      count = 4
    }
    return (word, count)
  }

JSONParser.swift:validateNonASCIIRun.code:
@inlinable
  @inline(never)
  mutating func validateNonASCIIRun(
    base: UnsafeRawPointer,
    from: Int,
    to: Int,
    reportAt: Int?
  ) throws(JSONParsingError) {
    if streamValidateUTF8(base: base, from: from, to: to) { return }
    var i = from
    while i < to {
      let lead = base.load(fromByteOffset: i, as: UInt8.self)
      if lead < .utf8ContinuationFloor {
        i &+= 1
        continue
      }
      guard lead >= .utf8TwoByteMinimum, lead <= .utf8MaximumLead else { throw self.error(.invalidUTF8, at: reportAt ?? i) }
      let needed = Self.sequenceLength(lead)
      guard i &+ needed <= to else { throw self.error(.invalidUTF8, at: reportAt ?? i) }
      for offset in 1..<needed {
        let continuation = base.load(fromByteOffset: i &+ offset, as: UInt8.self)
        guard continuation >= .utf8ContinuationFloor, continuation < .utf8TwoByteFloor else {
          throw self.error(.invalidUTF8, at: reportAt ?? i)
        }
      }
      let second = base.load(fromByteOffset: i &+ 1, as: UInt8.self)
      switch lead {
      case .utf8ThreeByteFloor:
        guard second >= .utf8ThreeByteLowerBound else { throw self.error(.invalidUTF8, at: reportAt ?? i) }
      case .utf8SurrogateLead:
        guard second <= .utf8SurrogateCeiling else { throw self.error(.invalidUTF8, at: reportAt ?? i) }
      case .utf8FourByteFloor:
        guard second >= .utf8FourByteLowerBound else { throw self.error(.invalidUTF8, at: reportAt ?? i) }
      case .utf8MaximumLead:
        guard second <= .utf8MaximumSecond else { throw self.error(.invalidUTF8, at: reportAt ?? i) }
      default:
        break
      }
      i &+= needed
    }
  }

JSONParser.swift:validateUTF8IfNeeded.code:
@inlinable
  @inline(__always)
  mutating func validateUTF8IfNeeded(
    base: UnsafeRawPointer,
    from: Int,
    to: Int,
    containsNonASCII: Bool,
    reportAt: Int?
  ) throws(JSONParsingError) {
    guard containsNonASCII else { return }
    try self.validateNonASCIIRun(base: base, from: from, to: to, reportAt: reportAt)
  }

JSONParserBlocks.swift:consumeStructural.code:
@inlinable
    @inline(never)
    mutating func consumeStructuralBlocks<Sink: StreamParseSink & ~Copyable>(
      base: UnsafeRawPointer,
      from: Int,
      to: Int,
      state: inout State,
      depth: inout Int,
      containers: inout UInt64,
      into sink: inout Sink
    ) throws(JSONParsingError) -> Int {
      var p = from
      // The grid moves with the tokens, so carries are always zero: the walk only consumes tokens
      // that finish in the block, and re-anchors at the end of one that runs past it. Measured: a
      // fixed grid with real carries classifies every long string's interior, GSoC/LLM -9%/-20%.
      outer: while p &+ 64 <= to {
        let classes = stream_parsing_classify_structural_block(
          base.advanced(by: p).assumingMemoryBound(to: UInt8.self), 0, 0
        )
        // Anything unusual is the scalar loop's, from this block's first byte, so the byte an
        // error names is the byte the scalar loop names.
        if classes.needs_scalar != 0 { return p }
        // The gate: a block strikes with no whitespace outside strings (nothing for the `tzcnt` to
        // buy over the ladder's scan) or dense `starts` (Mesh); four in a row give the walk up
        // until `probeBlockWalk` re-arms it. Census in NEW_ARCHITECTURE.md. x86 gets the verdict
        // whole from the kernel: baseline x86-64 has no `popcnt` (`nonzeroBitCount` was 17
        // instructions a block).
        #if arch(x86_64)
          let strike = classes.strike != 0
        #else
          let strike =
            classes.no_outer_whitespace != 0
            || classes.starts.nonzeroBitCount >= Int(STREAM_PARSING_BLOCK_WALK_DENSE_STARTS)
        #endif
        if strike {
          self.blockWalkStrikes &+= 1
          if self.blockWalkStrikes >= 4 {
            self.blockWalkGivenUp = true
            self.blockWalkProbeCountdown = Self.blockWalkProbeKilobytes
            if self.windowThreshold == .max {
              self.windowThreshold = Self.blockWalkProbeChunk
              self.blockWalkProbeLowered = true
            }
            return ~p
          }
        } else if self.blockWalkStrikes != 0 {
          // Consecutive, not cumulative. Measured: counting GSoC's odd whitespace-free blocks up
          // reached four and threw its win away (+18.1% -> -0.8%).
          self.blockWalkStrikes = 0
        }
        let containsNonASCII = classes.non_ascii != 0
        var mask = classes.starts

        while mask != 0 {
          let bit = mask.trailingZeroBitCount
          let at = p &+ bit
          let byte = base.load(fromByteOffset: at, as: UInt8.self)
          let raw = state.rawValue

          // The quote arm, ahead of the ladder exactly as it is in `consumeStructural`: a key or
          // a string value, in a state that admits one.
          if byte == .asciiQuote, raw <= State.firstKey.rawValue,
            raw != State.afterValue.rawValue
          {
            // Bits 0...bit. `1 << bit` is in range for every bit of a 64-bit mask, and the
            // wrapping `&<< 1` folds bit 63 to zero, whose `&- 1` is all ones -- which is the
            // right answer there (nothing lies above byte 63).
            let consumed = ((UInt64(1) &<< UInt64(bit)) &<< 1) &- 1
            let closers = classes.quote & ~consumed
            // No closing quote in this block: the scalar arm's scan, restated. Measured: handing
            // the token back re-classified the block per string (Qwen workspace -26%, LLM -3%).
            guard closers != 0 else {
              let run = streamStringRun(base: base, from: at &+ 1, to: to)
              let closed =
                run.end < to && base.load(fromByteOffset: run.end, as: UInt8.self) == .asciiQuote
              if raw <= State.firstValue.rawValue {
                self.isKeyToken = false
                guard closed else {
                  if run.end < to {
                    let next = try self.consumeEscapedStringInRun(
                      base: base, quoteAt: at, from: at &+ 1, to: to, run: run, into: &sink
                    )
                    state = self.state
                    if !state.isStructural { return next }
                    if next &- p >= 64 {
                      p = next
                      continue outer
                    }
                    mask &= UInt64.max &<< UInt64(next &- p)
                    continue
                  }
                  // Cut by the chunk end: `consumeStringRun` takes the token from the opening
                  // quote, exactly as it does when the scalar arm hands it over.
                  self.stringBeginPending = true
                  state = .inString
                  return at &+ 1
                }
                do throws(JSONParsingError) {
                  try self.validateUTF8IfNeeded(
                    base: base, from: at &+ 1, to: run.end,
                    containsNonASCII: run.containsNonASCII, reportAt: nil
                  )
                } catch {
                  try self.record(
                    .stringBegin, start: at, length: 1, end: at &+ 1, base: base, into: &sink
                  )
                  try Self.fail(error)
                }
                try self.record(
                  .string, start: at &+ 1, length: run.end &- at &- 1, end: run.end &+ 1,
                  base: base, into: &sink
                )
                state = .afterValue
              } else {
                guard closed else {
                  self.isKeyToken = true
                  self.bufferCount = 0
                  self.keyContainsNonASCII = false
                  state = .inKey
                  return at &+ 1
                }
                try self.emitKeyInPlace(
                  base: base, from: at &+ 1, to: run.end, containsNonASCII: run.containsNonASCII,
                  into: &sink
                )
                state = .afterKey
              }
              if run.end &+ 1 &- p >= 64 {
                p = run.end &+ 1
                continue outer
              }
              mask &= UInt64.max &<< UInt64(run.end &+ 1 &- p)
              continue
            }
            let closeBit = closers.trailingZeroBitCount
            let closeAt = p &+ closeBit
            let escapes =
              classes.backslash & ~consumed & ((UInt64(1) &<< UInt64(closeBit)) &- 1)

            if escapes != 0 {
              // A key with an escape in it is rare enough not to be worth a second decoder here;
              // the scalar loop buffers it through `consumeKeyRun` as it does today.
              guard raw <= State.firstValue.rawValue else { return at }
              // A string value with an escape, decoded as the scalar run decodes it. It does not
              // fuse the following comma (the fields do not hold this walk's container stack), so
              // a finished token comes back `.afterValue` and the walk takes the comma itself.
              self.isKeyToken = false
              let run = streamStringRun(base: base, from: at &+ 1, to: to)
              let next = try self.consumeEscapedStringInRun(
                base: base, quoteAt: at, from: at &+ 1, to: to, run: run, into: &sink
              )
              state = self.state
              // A token the chunk cut, or an escape left to the per-byte states, is non-structural.
              if !state.isStructural { return next }
              if next &- p >= 64 {
                p = next
                continue outer
              }
              mask &= UInt64.max &<< UInt64(next &- p)
              continue
            }

            if raw <= State.firstValue.rawValue {
              self.isKeyToken = false
              do throws(JSONParsingError) {
                try self.validateUTF8IfNeeded(
                  base: base, from: at &+ 1, to: closeAt, containsNonASCII: containsNonASCII,
                  reportAt: nil
                )
              } catch {
                // `stringBegin` precedes the error on the call-per-event path; keep that order.
                try self.record(
                  .stringBegin, start: at, length: 1, end: at &+ 1, base: base, into: &sink
                )
                try Self.fail(error)
              }
              try self.record(
                .string, start: at &+ 1, length: closeAt &- at &- 1, end: closeAt &+ 1,
                base: base, into: &sink
              )
              state = .afterValue
            } else {
              try self.emitKeyInPlace(
                base: base, from: at &+ 1, to: closeAt, containsNonASCII: containsNonASCII,
                into: &sink
              )
              state = .afterKey
            }
            if closeBit == 63 {
              p = closeAt &+ 1
              continue outer
            }
            mask &= UInt64.max &<< UInt64(closeBit &+ 1)
            continue
          }

          if raw <= State.firstValue.rawValue {
            switch byte {
            case .asciiObjectStart:
              let disposition = try self.recordContainerOpen(
                object: true, end: at &+ 1, into: &sink
              )
              guard depth < Self.maximumDepth else {
                try Self.fail(.depthExceeded, byteOffset: self.consumedByteCount &+ at)
              }
              Self.pushContainer(object: true, depth: &depth, containers: &containers)
              // The skip scanner owns the subtree from here; the dispatcher re-enters it. Measured:
              // skipping in place here lost where subtrees outlive the block (sweep mean +4.07% vs
              // +5.24%) -- see NEW_ARCHITECTURE.md, "Skipping a subtree inside the block walk".
              if disposition != .stream {
                self.skipEndDepth = UInt8(truncatingIfNeeded: depth &- 1)
                state = .skipping
                return at &+ 1
              }
              state = .firstKey
            case .asciiArrayStart:
              let disposition = try self.recordContainerOpen(
                object: false, end: at &+ 1, into: &sink
              )
              guard depth < Self.maximumDepth else {
                try Self.fail(.depthExceeded, byteOffset: self.consumedByteCount &+ at)
              }
              Self.pushContainer(object: false, depth: &depth, containers: &containers)
              if disposition != .stream {
                self.skipEndDepth = UInt8(truncatingIfNeeded: depth &- 1)
                state = .skipping
                return at &+ 1
              }
              state = .firstValue
            case .asciiArrayEnd:
              guard state == .firstValue, !Self.topIsObject(depth: depth, containers: containers)
              else {
                try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
              }
              try self.record(
                .endArray, start: at, length: 1, end: at &+ 1, base: base, into: &sink
              )
              depth &-= 1
              if depth == 0 {
                state = .done
                return at &+ 1
              }
              state = .afterValue
            // `"` was taken ahead of the ladder.
            case .asciiLowerT:
              guard to &- at >= 4,
                UInt32(littleEndian: base.loadUnaligned(fromByteOffset: at, as: UInt32.self))
                  == 0x6575_7274
              else { return at }
              try self.record(
                .boolean, start: at, length: 4, end: at &+ 4, extra: 1, base: base, into: &sink
              )
              state = .afterValue
              if bit &+ 4 >= 64 {
                p = at &+ 4
                continue outer
              }
              mask &= UInt64.max &<< UInt64(bit &+ 4)
              continue
            case .asciiLowerF:
              guard to &- at >= 5,
                UInt32(littleEndian: base.loadUnaligned(fromByteOffset: at &+ 1, as: UInt32.self))
                  == 0x6573_6c61
              else { return at }
              try self.record(
                .boolean, start: at, length: 5, end: at &+ 5, base: base, into: &sink
              )
              state = .afterValue
              if bit &+ 5 >= 64 {
                p = at &+ 5
                continue outer
              }
              mask &= UInt64.max &<< UInt64(bit &+ 5)
              continue
            case .asciiLowerN:
              guard to &- at >= 4,
                UInt32(littleEndian: base.loadUnaligned(fromByteOffset: at, as: UInt32.self))
                  == 0x6c6c_756e
              else { return at }
              try self.record(.null, start: at, length: 4, end: at &+ 4, base: base, into: &sink)
              state = .afterValue
              if bit &+ 4 >= 64 {
                p = at &+ 4
                continue outer
              }
              mask &= UInt64.max &<< UInt64(bit &+ 4)
              continue
            case .asciiDash, .asciiZero ... .asciiNine:
              // The extent is deliberately *not* taken from the masks: `12abc` has to report
              // `unexpectedToken` at the `a`, which is what the grammar walk behind
              // `streamNumberRunEnd` does and what a mask over the number's byte class would not.
              let end = streamNumberRunEnd(base: base, from: at, to: to)
              guard end < to else {
                // The token may continue in the next chunk, so it goes to the per-byte path
                // whole, exactly as the scalar arm hands it over.
                self.resetNumber()
                state = .number
                return at
              }
              try self.emitNumber(base: base, from: at, to: end, into: &sink, reportAt: end)
              state = .afterValue
              if end &- p >= 64 {
                p = end
                continue outer
              }
              mask &= UInt64.max &<< UInt64(end &- p)
              continue
            default:
              try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
            }

          } else if raw == State.afterValue.rawValue {
            switch byte {
            case .asciiComma:
              guard depth > 0 else {
                try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
              }
              state = Self.topIsObject(depth: depth, containers: containers) ? .key : .value
            case .asciiArrayEnd:
              guard depth > 0, !Self.topIsObject(depth: depth, containers: containers) else {
                try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
              }
              try self.record(
                .endArray, start: at, length: 1, end: at &+ 1, base: base, into: &sink
              )
              depth &-= 1
              if depth == 0 {
                state = .done
                return at &+ 1
              }
              state = .afterValue
            case .asciiObjectEnd:
              guard Self.topIsObject(depth: depth, containers: containers) else {
                try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
              }
              try self.record(
                .endObject, start: at, length: 1, end: at &+ 1, base: base, into: &sink
              )
              depth &-= 1
              if depth == 0 {
                state = .done
                return at &+ 1
              }
              state = .afterValue
            default:
              try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
            }

          } else if raw <= State.firstKey.rawValue {
            switch byte {
            // `"` was taken ahead of the ladder.
            case .asciiObjectEnd:
              guard state == .firstKey, Self.topIsObject(depth: depth, containers: containers)
              else {
                try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
              }
              try self.record(
                .endObject, start: at, length: 1, end: at &+ 1, base: base, into: &sink
              )
              depth &-= 1
              if depth == 0 {
                state = .done
                return at &+ 1
              }
              state = .afterValue
            default:
              try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
            }

          } else if raw == State.afterKey.rawValue {
            guard byte == .asciiColon else {
              try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
            }
            state = .value
          } else if raw == State.done.rawValue {
            try Self.fail(.trailingContent, byteOffset: self.consumedByteCount &+ at)
          } else {
            try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
          }
          // Every arm that falls through here consumed exactly its one byte.
          mask &= mask &- 1
        }

        // Mask exhausted: the rest of the block is whitespace and every string in it was finished,
        // so the next block is classifiable with nothing carried in.
        p &+= 64
      }
      return p
    }

