@usableFromInline
  enum ShapeOutcome {
    // The container the loop was entered on has closed; `state` is what the walk's close arm
    // would have set, and `cursor`/`k` sit just after the closing bracket.
    case closed
    // Something off-pattern. `state`, `cursor` and `k` describe a position the walk understands:
    // either just after a `[`/`,` in value state, or at a separator entry in `.afterValue`.
    case fellBack
  }

JSONParserShapes.swift:consumeNumericArr.code:
@inlinable
  @inline(never)
  mutating func consumeNumericArray<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    to n: Int,
    count: Int,
    indices: UnsafeMutablePointer<UInt32>,
    cursor: inout Int,
    k: inout Int,
    state: inout State,
    depth: inout Int,
    containers: inout UInt64,
    into sink: inout Sink
  ) throws(JSONParsingError) -> ShapeOutcome {
    let rootDepth = depth
    var expectingValue = true
    // Entered after `[` (`.firstValue`) or, mid-array, after a `,` (`.value`): the state says
    // whether a `]` may come next.
    var first = state == .firstValue
    while k < count {
      if expectingValue {
        var start = cursor
        var separatorEntry = k
        if streamIsWhitespace(base.load(fromByteOffset: start, as: UInt8.self)) {
          start = Int(indices[k])
          separatorEntry = k &+ 1
        }
        switch base.load(fromByteOffset: start, as: UInt8.self) {
        case .asciiDash, .asciiZero ... .asciiNine:
          guard separatorEntry < count else { break }
          let separator = Int(indices[separatorEntry])
          let separatorByte = base.load(fromByteOffset: separator, as: UInt8.self)
          guard separatorByte == .asciiComma || separatorByte == .asciiArrayEnd else { break }
          let info: NumberInfo
          if let long = self.parseLongDecimal(base: base, from: start, to: separator, chunkEnd: n) {
            info = long
          } else {
            do {
              info = try self.parseNumber(base: base, from: start, to: separator, reportAt: separator)
            } catch {
              break
            }
          }
          try self.recordNumber(
            start: start, length: separator &- start, end: separator, base: base, info: info, into: &sink
          )
          cursor = separator
          k = separatorEntry
          expectingValue = false
          continue
        case .asciiArrayStart:
          guard depth < Self.maximumDepth else { break }
          try self.record(.beginArray, start: start, length: 1, end: start &+ 1, base: base, into: &sink)
          Self.pushContainer(object: false, depth: &depth, containers: &containers)
          cursor = start &+ 1
          k = k &+ 1
          first = true
          continue
        case .asciiArrayEnd:
          guard first else { break }
          try self.record(.endArray, start: start, length: 1, end: start &+ 1, base: base, into: &sink)
          depth &-= 1
          cursor = start &+ 1
          k = k &+ 1
          if depth < rootDepth {
            state = depth == 0 ? .done : .afterValue
            return .closed
          }
          expectingValue = false
          continue
        default:
          break
        }
        state = first ? .firstValue : .value
        return .fellBack
      } else {
        let position = Int(indices[k])
        switch base.load(fromByteOffset: position, as: UInt8.self) {
        case .asciiComma:
          cursor = position &+ 1
          k &+= 1
          expectingValue = true
          first = false
          continue
        case .asciiArrayEnd:
          try self.record(.endArray, start: position, length: 1, end: position &+ 1, base: base, into: &sink)
          depth &-= 1
          cursor = position &+ 1
          k &+= 1
          if depth < rootDepth {
            state = depth == 0 ? .done : .afterValue
            return .closed
          }
          continue
        default:
          state = .afterValue
          return .fellBack
        }
      }
    }
    state = expectingValue ? (first ? .firstValue : .value) : .afterValue
    return .fellBack
  }

JSONParserShapes.swift:consumeObjectMemb.code:
@inlinable
  @inline(never)
  mutating func consumeObjectMembers<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    windowStart: Int,
    to n: Int,
    count: Int,
    indices: UnsafeMutablePointer<UInt32>,
    needsScan: UnsafeMutablePointer<UInt64>,
    nonASCII: UnsafeMutablePointer<UInt64>,
    cursor: inout Int,
    k: inout Int,
    state: inout State,
    depth: inout Int,
    containers: inout UInt64,
    into sink: inout Sink
  ) throws(JSONParsingError) -> ShapeOutcome {
    var first = state == .firstKey
    while true {
      // Key: three entries ahead must read quote, quote, colon, and nothing but whitespace may
      // sit between the cursor and the opening quote.
      guard k &+ 2 < count else { state = first ? .firstKey : .key; return .fellBack }
      let open = Int(indices[k])
      let close = Int(indices[k &+ 1])
      let colon = Int(indices[k &+ 2])
      guard base.load(fromByteOffset: open, as: UInt8.self) == .asciiQuote,
        base.load(fromByteOffset: close, as: UInt8.self) == .asciiQuote,
        base.load(fromByteOffset: colon, as: UInt8.self) == .asciiColon,
        open == cursor || streamIsWhitespace(base.load(fromByteOffset: cursor, as: UInt8.self))
      else { state = first ? .firstKey : .key; return .fellBack }
      // A scalar directly after a quote has no index entry, so the key-to-colon gap is checked
      // before the key is emitted; compact JSON takes the adjacent-colon compare without a scan.
      guard colon == close &+ 1
        || streamWhitespaceEnd(base: base, from: close &+ 1, to: colon) == colon
      else { state = first ? .firstKey : .key; return .fellBack }
      var keyNonASCII = false
      if close > open &+ 1 {
        let firstBlock = (open &+ 1 &- windowStart) &>> 6
        let lastBlock = (close &- 1 &- windowStart) &>> 6
        guard !Self.windowFlag(needsScan, firstBlock: firstBlock, lastBlock: lastBlock) else {
          state = first ? .firstKey : .key
          return .fellBack
        }
        keyNonASCII = Self.windowFlag(nonASCII, firstBlock: firstBlock, lastBlock: lastBlock)
      }
      try self.validateUTF8IfNeeded(
        base: base, from: open &+ 1, to: close, containsNonASCII: keyNonASCII, reportAt: close
      )
      try self.record(.key, start: open &+ 1, length: close &- open &- 1, end: close &+ 1, base: base, into: &sink)
      cursor = colon &+ 1
      k &+= 3
      first = false

      // Value: at the cursor, or at the next entry when the cursor is on whitespace.
      var start = cursor
      var afterValueEntry = k
      // A complete key/colon can be the last bytes of an incomplete chunk. Leave the
      // value pending before inspecting its first byte; it belongs to the next parse call.
      guard start < n else { state = .value; return .fellBack }
      if streamIsWhitespace(base.load(fromByteOffset: start, as: UInt8.self)) {
        guard k < count else { state = .value; return .fellBack }
        start = Int(indices[k])
        afterValueEntry = k &+ 1
      }
      switch base.load(fromByteOffset: start, as: UInt8.self) {
      case .asciiQuote:
        // A quote is always an entry: `start == indices[k]`, and the closing quote is next.
        guard k &+ 1 < count else { state = .value; return .fellBack }
        let closeQuote = Int(indices[k &+ 1])
        var valueNonASCII = false
        if closeQuote > start &+ 1 {
          let firstBlock = (start &+ 1 &- windowStart) &>> 6
          let lastBlock = (closeQuote &- 1 &- windowStart) &>> 6
          guard !Self.windowFlag(needsScan, firstBlock: firstBlock, lastBlock: lastBlock) else {
            state = .value
            return .fellBack
          }
          valueNonASCII = Self.windowFlag(nonASCII, firstBlock: firstBlock, lastBlock: lastBlock)
        }
        self.isKeyToken = false
        if closeQuote > start &+ 1 {
          do {
            try self.validateUTF8IfNeeded(
              base: base, from: start &+ 1, to: closeQuote, containsNonASCII: valueNonASCII,
              reportAt: nil
            )
          } catch {
            try self.record(.stringBegin, start: start, length: 1, end: start &+ 1, base: base, into: &sink)
            throw error
          }
        }
        try self.record(.string, start: start &+ 1, length: closeQuote &- start &- 1, end: closeQuote &+ 1, base: base, into: &sink)
        cursor = closeQuote &+ 1
        k &+= 2
      case .asciiDash, .asciiZero ... .asciiNine:
        guard afterValueEntry < count else { state = .value; return .fellBack }
        let separator = Int(indices[afterValueEntry])
        let separatorByte = base.load(fromByteOffset: separator, as: UInt8.self)
        guard separatorByte == .asciiComma || separatorByte == .asciiObjectEnd else {
          state = .value
          return .fellBack
        }
        let info: NumberInfo
        do {
          info = try self.parseNumber(base: base, from: start, to: separator, reportAt: separator)
        } catch {
          state = .value
          return .fellBack
        }
        try self.recordNumber(
          start: start, length: separator &- start, end: separator, base: base, info: info, into: &sink
        )
        cursor = separator
        k = afterValueEntry
      case .asciiLowerT, .asciiLowerF, .asciiLowerN:
        let byte = base.load(fromByteOffset: start, as: UInt8.self)
        let kind: UInt8 = byte == .asciiLowerT ? 0 : byte == .asciiLowerF ? 1 : 2
        let expected = Self.literalBytes[Int(kind)]
        var j = start &+ 1
        var index = 1
        while j < n && index < expected.count
          && base.load(fromByteOffset: j, as: UInt8.self) == expected[index]
        {
          index &+= 1
          j &+= 1
        }
        guard index == expected.count else { state = .value; return .fellBack }
        try self.record(kind == 2 ? .null : .boolean, start: start, length: j &- start, end: j, extra: kind == 0 ? 1 : 0, base: base, into: &sink)
        cursor = j
        k = afterValueEntry
      default:
        state = .value
        return .fellBack
      }

      // Separator: the next entry, with only whitespace before it.
      guard k < count else { state = .afterValue; return .fellBack }
      let position = Int(indices[k])
      guard position == cursor || streamIsWhitespace(base.load(fromByteOffset: cursor, as: UInt8.self))
      else { state = .afterValue; return .fellBack }
      switch base.load(fromByteOffset: position, as: UInt8.self) {
      case .asciiComma:
        cursor = position &+ 1
        k &+= 1
      case .asciiObjectEnd:
        try self.record(.endObject, start: position, length: 1, end: position &+ 1, base: base, into: &sink)
        depth &-= 1
        state = depth == 0 ? .done : .afterValue
        cursor = position &+ 1
        k &+= 1
        return .closed
      default:
        state = .afterValue
        return .fellBack
      }
    }
  }

JSONParserShapes.swift:parseLongDecimal.code:
@inlinable
  @inline(__always)
  func parseLongDecimal(base: UnsafeRawPointer, from: Int, to: Int, chunkEnd: Int) -> NumberInfo? {
    guard to &- from > 16, from &+ 32 <= chunkEnd else { return nil }
    var magnitude: UInt64 = 0
    var exponent: Int32 = 0
    var digitCount: UInt32 = 0
    var flags: UInt32 = 0
    guard stream_parsing_decimal32(
      base.advanced(by: from).assumingMemoryBound(to: UInt8.self), to &- from,
      &magnitude, &exponent, &digitCount, &flags
    ) != 0 else { return nil }
    return NumberInfo(
      magnitude: magnitude, exponent: Int16(clamping: Int(exponent)),
      digitCount: UInt16(truncatingIfNeeded: Int(digitCount)),
      flags: NumberInfo.Flags(rawValue: UInt16(truncatingIfNeeded: flags))
    )
  }

JSONParserShapes.swift:parseNumber.code:
@usableFromInline
  @_transparent
  func parseNumber(
    base: UnsafeRawPointer, from: Int, to: Int, reportAt: Int
  ) throws(JSONParsingError) -> NumberInfo {
    if to &- from <= 8, to >= 8,
      base.load(fromByteOffset: from, as: UInt8.self) != .asciiZero || to &- from == 1,
      let magnitude = streamShortInteger(base: base, from: from, end: to)
    {
      return NumberInfo(
        magnitude: magnitude, exponent: 0,
        digitCount: UInt16(truncatingIfNeeded: to &- from), flags: []
      )
    }
    var flags = NumberInfo.Flags()
    var i = from
    if i < to, base.load(fromByteOffset: i, as: UInt8.self) == .asciiDash {
      flags.insert(.negative)
      i &+= 1
    }
    var magnitude: UInt64 = 0
    let integerStart = i
    i = streamAccumulateDigits(base: base, from: i, to: to, into: &magnitude)
    let integerDigits = i &- integerStart
    guard integerDigits > 0 else { throw self.error(.invalidNumber, at: reportAt) }
    if integerDigits > 1, base.load(fromByteOffset: integerStart, as: UInt8.self) == .asciiZero {
      throw self.error(.invalidNumber, at: reportAt)
    }
    var fractionDigits = 0
    if i < to, base.load(fromByteOffset: i, as: UInt8.self) == .asciiDot {
      flags.insert(.fraction)
      i &+= 1
      let fractionStart = i
      i = streamAccumulateDigits(base: base, from: i, to: to, into: &magnitude)
      fractionDigits = i &- fractionStart
      if fractionDigits == 0 { throw self.error(.invalidNumber, at: reportAt) }
    }
    var explicitExponent: Int32 = 0
    var exponentNegative = false
    if i < to, (base.load(fromByteOffset: i, as: UInt8.self) | 0x20) == .asciiLowerE {
      flags.insert(.exponent)
      i &+= 1
      if i < to {
        let sign = base.load(fromByteOffset: i, as: UInt8.self)
        if sign == .asciiDash {
          exponentNegative = true
          i &+= 1
        } else if sign == .asciiPlus {
          i &+= 1
        }
      }
      let exponentStart = i
      while i < to {
        let digit = base.load(fromByteOffset: i, as: UInt8.self) &- .asciiZero
        guard digit < 10 else { break }
        if explicitExponent < 10_000 {
          explicitExponent = explicitExponent &* 10 &+ Int32(digit)
        }
        i &+= 1
      }
      if i == exponentStart { throw self.error(.invalidNumber, at: reportAt) }
    }
    if i != to { throw self.error(.invalidNumber, at: reportAt) }
    let totalDigits = integerDigits &+ fractionDigits
    if totalDigits > 19 { flags.insert(.overflowed) }
    let signedExponent = exponentNegative ? -explicitExponent : explicitExponent
    return NumberInfo(
      magnitude: magnitude,
      exponent: Int16(clamping: Int(signedExponent) &- fractionDigits),
      digitCount: UInt16(truncatingIfNeeded: totalDigits),
      flags: flags
    )
  }

JSONParserSkip.swift:consumeSkipBlocks.code:
@inlinable
    @inline(never)
    mutating func consumeSkipBlocks<Sink: StreamParseSink & ~Copyable>(
      base: UnsafeRawPointer,
      from: Int,
      to: Int,
      state: inout State,
      depth: inout Int,
      containers: inout UInt64,
      into sink: inout Sink
    ) throws(JSONParsingError) -> Int {
      let skipEnd = Int(self.skipEndDepth)
      // Both carries describe the byte at `p`: `inStringCarry` is all ones inside a string, and
      // `endsOddCarry` is one when the byte before `p` was an unescaped backslash. They are
      // updated only after a block is accepted, so a block handed to the scalar loop is handed
      // to it with the state of its *first* byte.
      var inStringCarry: UInt64 = 0
      var endsOddCarry: UInt64 = 0
      // Deferred UTF-8 validation: the first block with a non-ASCII byte since the last settlement,
      // or -1. Settled at the first all-ASCII block -- short-ranged, and safe because a sequence
      // cannot straddle a block with no high bit in it.
      var validateFrom = -1
      var p = from
      while p &+ 64 <= to {
        let classes = stream_parsing_classify_skip_block(
          base.advanced(by: p).assumingMemoryBound(to: UInt8.self), inStringCarry, endsOddCarry
        )
        // Anything unusual is the scalar loop's, from this block's first byte, so the byte an
        // error names is the byte the scalar loop names.
        if classes.needs_scalar != 0 { break }

        if classes.non_ascii != 0 {
          if validateFrom < 0 { validateFrom = p }
        } else {
          validateFrom = try self.settleValidation(base: base, from: validateFrom, to: p)
        }

        var brackets = classes.brackets
        while brackets != 0 {
          let at = p &+ brackets.trailingZeroBitCount
          brackets &= brackets &- 1
          // The byte spells its kind: openers carry bit 1, braces bit 5. One load from a line the
          // classifier just read beats two more movemasks.
          let byte = base.load(fromByteOffset: at, as: UInt8.self)
          let isObject = byte & 0x20 != 0
          if byte & 0x02 != 0 {
            // The cap is checked per open, as the scalar loop checks it, so it reports at the
            // breaching bracket; a per-block popcount verdict costs four instructions every block.
            guard depth < Self.maximumDepth else {
              validateFrom = try self.settleValidation(base: base, from: validateFrom, to: at)
              try Self.fail(.depthExceeded, byteOffset: self.consumedByteCount &+ at)
            }
            Self.pushContainer(object: isObject, depth: &depth, containers: &containers)
          } else {
            guard depth > 0, isObject == Self.topIsObject(depth: depth, containers: containers)
            else {
              // Everything outstanding is earlier in the document than this bracket, so it is
              // reported first — the order a byte-fed parse would have found them in.
              validateFrom = try self.settleValidation(base: base, from: validateFrom, to: at)
              try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
            }
            if depth &- 1 == skipEnd {
              validateFrom = try self.settleValidation(base: base, from: validateFrom, to: at)
              // The event precedes the depth/state updates, exactly as the structural run orders
              // them, so a failure the check surfaces leaves the same parser state behind.
              try self.record(
                isObject ? .endObject : .endArray,
                start: at, length: 1, end: at &+ 1, base: base, into: &sink
              )
              depth &-= 1
              state = depth == 0 ? .done : .afterValue
              return at &+ 1
            }
            depth &-= 1
          }
        }

        inStringCarry = classes.in_string
        endsOddCarry = classes.ends_odd
        p &+= 64
      }

      // Hand over at `p`, with the state the carries describe. A byte after an unescaped
      // backslash is an escape selector whatever else it is; otherwise the parity says it.
      if endsOddCarry != 0 {
        state = .skippingEscape
      } else if inStringCarry != 0 {
        state = .skippingString
        // A sequence may straddle the handover. Back up to its lead so the scalar loop reads it
        // whole — and so the deferred validation below stops before it, exactly where the string
        // loop's own trim would have.
        p = try self.trimmingIncompleteUTF8(base: base, from: from, to: p)
      }
      validateFrom = try self.settleValidation(base: base, from: validateFrom, to: p)
      return p
    }

JSONParserSkip.swift:consumeSkipRun.code:
@inlinable
  @inline(never)
  mutating func consumeSkipRun<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    from: Int,
    to: Int,
    into sink: inout Sink
  ) throws(JSONParsingError) -> Int {
    var i = from
    var state = self.state
    var depth = self.depth
    var containers = self.containers
    defer {
      self.state = state
      self.depth = depth
      self.containers = containers
    }
    // A chunk cut the string (or its escape): finish the string first, then fall into the
    // structural loop below.
    if state != .skipping {
      guard let end = try self.resumeSkippedString(base: base, from: i, to: to, state: &state)
      else { return to }
      i = end
    }

    #if arch(arm64) || arch(x86_64)
      // The block path is out of line to keep its d8 save out of this prologue, which every
      // byte-fed call inside a skipped subtree pays (measured inlined: byte-fed Twitter escaped
      // discarding -5.1%). `blockKernelsAvailable` (a load on x86) is tested last so a byte-fed
      // call, failing `i &+ 64 <= to`, never reads it.
      if state == .skipping, i &+ 64 <= to, self.blockKernelsAvailable {
        // Copies scoped to this branch, not the run's locals: taking the address of those makes
        // `var depth = self.depth` an address-taken init whose store lands in the entry block, on
        // every byte-fed call that never gets here.
        var blockState = state
        var blockDepth = depth
        var blockContainers = containers
        // Written back on the way out of this scope whatever the exit is, so a throw from the
        // block path leaves the same parser state behind that the scalar loop's own throws do.
        defer {
          state = blockState
          depth = blockDepth
          containers = blockContainers
        }
        i = try self.consumeSkipBlocks(
          base: base, from: i, to: to, state: &blockState, depth: &blockDepth,
          containers: &blockContainers, into: &sink
        )
        // A structural state means the block path delivered the matching close.
        if blockState.isStructural { return i }
        if blockState != .skipping {
          guard
            let end = try self.resumeSkippedString(
              base: base, from: i, to: to, state: &blockState
            )
          else { return to }
          i = end
        }
      }
    #endif

    while i < to {
      let scanned = streamWhitespaceEndByte(base: base, from: i, to: to)
      i = scanned.end
      if i == to { break }
      let byte = scanned.byte
      let at = i
      i &+= 1
      switch byte {
      case .asciiObjectStart:
        guard depth < Self.maximumDepth else {
          try Self.fail(.depthExceeded, byteOffset: self.consumedByteCount &+ at)
        }
        Self.pushContainer(object: true, depth: &depth, containers: &containers)
      case .asciiArrayStart:
        guard depth < Self.maximumDepth else {
          try Self.fail(.depthExceeded, byteOffset: self.consumedByteCount &+ at)
        }
        Self.pushContainer(object: false, depth: &depth, containers: &containers)
      case .asciiObjectEnd:
        guard Self.topIsObject(depth: depth, containers: containers) else {
          try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
        }
        if depth &- 1 == self.skipEndDepth {
          // The event precedes the depth/state updates, exactly as the structural run orders
          // them, so a failure the check surfaces leaves the same parser state behind.
          try self.record(.endObject, start: at, length: 1, end: i, base: base, into: &sink)
          depth &-= 1
          state = depth == 0 ? .done : .afterValue
          return i
        }
        depth &-= 1
      case .asciiArrayEnd:
        guard depth > 0, !Self.topIsObject(depth: depth, containers: containers) else {
          try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
        }
        if depth &- 1 == self.skipEndDepth {
          try self.record(.endArray, start: at, length: 1, end: i, base: base, into: &sink)
          depth &-= 1
          state = depth == 0 ? .done : .afterValue
          return i
        }
        depth &-= 1
      case .asciiQuote:
        guard let end = try self.skipStringBody(base: base, from: i, to: to, state: &state) else {
          return to
        }
        i = end
      case .asciiComma, .asciiColon:
        break
      case .asciiDash, .asciiDot, .asciiPlus, .asciiUpperE, .asciiZero ... .asciiNine:
        // The whole byte class in one scan, no grammar walk. `.`, `+` and `E` are here because a
        // number the chunk cut resumes at any byte of its class (`e` is in the letters arm).
        i = streamNumberRunEnd(base: base, from: at, to: to)
      case .asciiLowerA ... .asciiLowerZ:
        // Literal bytes, one at a time: `true` is four cheap iterations, and a skipped interior
        // does not validate the words.
        break
      default:
        try Self.fail(.unexpectedToken, byteOffset: self.consumedByteCount &+ at)
      }
    }
    return to
  }

JSONParserSkip.swift:resumeSkippedString.code:
@inlinable
  @inline(__always)
  mutating func resumeSkippedString(
    base: UnsafeRawPointer, from: Int, to: Int, state: inout State
  ) throws(JSONParsingError) -> Int? {
    var i = from
    if state == .skippingEscape {
      guard i < to else { return nil }
      // Escape selectors remain unchecked, but a backslash cannot hide a raw control byte.
      let selector = base.load(fromByteOffset: i, as: UInt8.self)
      guard selector >= .asciiSpace else {
        try Self.fail(.unterminatedString, byteOffset: self.consumedByteCount &+ i)
      }
      // Only ASCII selectors can be consumed as one byte. Let the string scanner validate
      // a non-ASCII selector and carry any incomplete sequence across the next boundary.
      if selector < .utf8ContinuationFloor { i &+= 1 }
      state = .skippingString
    }
    guard let end = try self.skipStringBody(base: base, from: i, to: to, state: &state) else {
      return nil
    }
    state = .skipping
    return end
  }

JSONParserSkip.swift:settleValidation.code:
@inlinable
    @inline(__always)
    mutating func settleValidation(
      base: UnsafeRawPointer, from: Int, to: Int
    ) throws(JSONParsingError) -> Int {
      if from >= 0 {
        try self.validateNonASCIIRun(base: base, from: from, to: to, reportAt: nil)
      }
      return -1
    }

JSONParserSkip.swift:skipStringBody.code:
@inlinable
  mutating func skipStringBody(
    base: UnsafeRawPointer, from: Int, to: Int, state: inout State
  ) throws(JSONParsingError) -> Int? {
    var i = from
    while true {
      let run = streamStringRun(base: base, from: i, to: to)
      if run.end > i {
        let emitEnd =
          run.end == to ? try self.trimmingIncompleteUTF8(base: base, from: i, to: run.end) : run.end
        if emitEnd > i {
          try self.validateUTF8IfNeeded(
            base: base, from: i, to: emitEnd, containsNonASCII: run.containsNonASCII, reportAt: nil
          )
        }
        if emitEnd < run.end {
          try self.holdPendingUTF8(base: base, from: emitEnd, to: run.end)
        }
        i = run.end
      }
      guard i < to else {
        state = .skippingString
        return nil
      }
      let byte = base.load(fromByteOffset: i, as: UInt8.self)
      let byteAt = i
      i &+= 1
      if byte == .asciiQuote {
        return i
      } else if byte == .asciiBackslash {
        guard i < to else {
          state = .skippingEscape
          return nil
        }
        // Match the cross-chunk escape path: selectors are loose, raw controls are not.
        let selector = base.load(fromByteOffset: i, as: UInt8.self)
        guard selector >= .asciiSpace else {
          throw self.error(.unterminatedString, at: i)
        }
        // Leave non-ASCII bytes for the next run's UTF-8 validation instead of hiding
        // a lead or continuation byte behind the backslash.
        if selector < .utf8ContinuationFloor { i &+= 1 }
      } else {
        throw self.error(.unterminatedString, at: byteAt)
      }
    }
  }

JSONParserWindow.swift:consumeGapScalar.code:
@inlinable
  @inline(__always)
  mutating func consumeGapScalar<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    at pos: Int,
    to n: Int,
    into sink: inout Sink
  ) throws(JSONParsingError) -> Int? {
    let byte = base.load(fromByteOffset: pos, as: UInt8.self)
    switch byte {
    case .asciiDash, .asciiZero ... .asciiNine:
      let end = streamNumberRunEnd(base: base, from: pos, to: n)
      guard end < n else { return nil }
      let info = try self.parseNumber(base: base, from: pos, to: end, reportAt: end)
      try self.recordNumber(start: pos, length: end &- pos, end: end, base: base, info: info, into: &sink)
      return end
    case .asciiLowerT, .asciiLowerF, .asciiLowerN:
      let kind: UInt8 = byte == .asciiLowerT ? 0 : byte == .asciiLowerF ? 1 : 2
      let expected = Self.literalBytes[Int(kind)]
      var j = pos &+ 1
      var index = 1
      while j < n && index < expected.count {
        if base.load(fromByteOffset: j, as: UInt8.self) != expected[index] {
          throw self.error(.invalidLiteral, at: j)
        }
        index &+= 1
        j &+= 1
      }
      guard index == expected.count else { return nil }
      try self.record(kind == 2 ? .null : .boolean, start: pos, length: j &- pos, end: j, extra: kind == 0 ? 1 : 0, base: base, into: &sink)
      return j
    default:
      throw self.error(.unexpectedToken, at: pos)
    }
  }

JSONParserWindow.swift:consumeWindow.code:
@inlinable
  @inline(never)
  mutating func consumeWindow<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    windowStart: Int,
    windowEnd: Int,
    to n: Int,
    from: Int,
    count: Int,
    entry: inout Int,
    indices: UnsafeMutablePointer<UInt32>,
    needsScan: UnsafeMutablePointer<UInt64>,
    nonASCII: UnsafeMutablePointer<UInt64>,
    into sink: inout Sink
  ) throws(JSONParsingError) -> Int {
    var state = self.state
    var depth = self.depth
    var containers = self.containers
    var k = entry
    defer {
      self.state = state
      self.depth = depth
      self.containers = containers
      entry = k
    }
    var cursor = from
    while true {
      let next = k < count ? Int(indices[k]) : windowEnd
      if cursor < next {
        let gapByte = base.load(fromByteOffset: cursor, as: UInt8.self)
        if !streamIsWhitespace(gapByte) {
          switch state {
          case .value, .firstValue:
            guard let end = try self.consumeGapScalar(base: base, at: cursor, to: n, into: &sink)
            else { return cursor }
            state = .afterValue
            cursor = end
            continue
          case .done:
            throw self.error(.trailingContent, at: cursor)
          default:
            throw self.error(.unexpectedToken, at: cursor)
          }
        }
        cursor = next
      }
      guard k < count else { return Swift.max(cursor, windowEnd) }
      let pos = next
      let byte = base.load(fromByteOffset: pos, as: UInt8.self)
      switch state {
      case .value, .firstValue:
        switch byte {
        case .asciiObjectStart:
          // The dispatcher sends `beginObject` and then rejects the depth; recorded, the event
          // precedes the error in the same order.
          let disposition = try self.recordContainerOpen(object: true, end: pos &+ 1, into: &sink)
          guard depth < Self.maximumDepth else { throw self.error(.depthExceeded, at: pos) }
          Self.pushContainer(object: true, depth: &depth, containers: &containers)
          cursor = pos &+ 1
          k &+= 1
          if disposition != .stream {
            // The walk hands the cursor back with the skip state set; `parseWindows` routes it
            // through `dispatchOnce` into the skip scanner, and the index resync picks the walk
            // up wherever the skip stops.
            self.skipEndDepth = UInt8(truncatingIfNeeded: depth &- 1)
            state = .skipping
            return cursor
          }
          state = .firstKey
          _ = try self.consumeObjectMembers(
            base: base, windowStart: windowStart, to: n, count: count, indices: indices,
            needsScan: needsScan, nonASCII: nonASCII, cursor: &cursor, k: &k,
            state: &state, depth: &depth, containers: &containers, into: &sink
          )
        case .asciiArrayStart:
          let disposition = try self.recordContainerOpen(object: false, end: pos &+ 1, into: &sink)
          guard depth < Self.maximumDepth else { throw self.error(.depthExceeded, at: pos) }
          Self.pushContainer(object: false, depth: &depth, containers: &containers)
          cursor = pos &+ 1
          k &+= 1
          if disposition != .stream {
            self.skipEndDepth = UInt8(truncatingIfNeeded: depth &- 1)
            state = .skipping
            return cursor
          }
          state = .firstValue
          // A numeric array subtree is a shape loop's; it decides in two loads whether this is one.
          if k < count {
            _ = try self.consumeNumericArray(
              base: base, to: n, count: count, indices: indices, cursor: &cursor, k: &k,
              state: &state, depth: &depth, containers: &containers, into: &sink
            )
          }
        case .asciiArrayEnd:
          guard state == .firstValue, !Self.topIsObject(depth: depth, containers: containers)
          else { throw self.error(.unexpectedToken, at: pos) }
          try self.record(.endArray, start: pos, length: 1, end: pos &+ 1, base: base, into: &sink)
          depth &-= 1
          state = depth == 0 ? .done : .afterValue
          cursor = pos &+ 1
          k &+= 1
        case .asciiQuote:
          guard k &+ 1 < count else { return pos }
          let close = Int(indices[k &+ 1])
          self.isKeyToken = false
          if close > pos &+ 1 {
            let firstBlock = (pos &+ 1 &- windowStart) &>> 6
            let lastBlock = (close &- 1 &- windowStart) &>> 6
            if Self.windowFlag(needsScan, firstBlock: firstBlock, lastBlock: lastBlock) {
              try self.record(.stringBegin, start: pos, length: 1, end: pos &+ 1, base: base, into: &sink)
              if let handedBack = try self.scanStringValue(
                base: base, from: pos &+ 1, to: close, into: &sink
              ) {
                state = .escape
                return handedBack
              }
              try self.record(.stringEnd, start: close, length: 1, end: close &+ 1, base: base, into: &sink)
              state = .afterValue
              cursor = close &+ 1
              k &+= 2
              continue
            }
            // One record for the whole string. The dispatcher sends `stringBegin` before it
            // scans, so a bad byte must still leave that event delivered before the error.
            do {
              try self.validateUTF8IfNeeded(
                base: base, from: pos &+ 1, to: close,
                containsNonASCII: Self.windowFlag(
                  nonASCII, firstBlock: firstBlock, lastBlock: lastBlock
                ),
                reportAt: nil
              )
            } catch {
              try self.record(.stringBegin, start: pos, length: 1, end: pos &+ 1, base: base, into: &sink)
              throw error
            }
          }
          try self.record(.string, start: pos &+ 1, length: close &- pos &- 1, end: close &+ 1, base: base, into: &sink)
          state = .afterValue
          cursor = close &+ 1
          k &+= 2
        default:
          // A number or literal that followed whitespace, indexed so the gap before it could
          // be skipped without a scan. Anything else is the error the dispatcher reports.
          guard let end = try self.consumeGapScalar(base: base, at: pos, to: n, into: &sink)
          else { return pos }
          state = .afterValue
          cursor = end
          k &+= 1
        }

      case .afterValue:
        switch byte {
        case .asciiComma:
          guard depth > 0 else { throw self.error(.unexpectedToken, at: pos) }
          state = Self.topIsObject(depth: depth, containers: containers) ? .key : .value
          cursor = pos &+ 1
          k &+= 1
          if state == .key {
            // Back in an object after a container value: the member loop takes over again.
            _ = try self.consumeObjectMembers(
              base: base, windowStart: windowStart, to: n, count: count, indices: indices,
              needsScan: needsScan, nonASCII: nonASCII, cursor: &cursor, k: &k,
              state: &state, depth: &depth, containers: &containers, into: &sink
            )
          } else if k < count {
            // Mid-array — after a non-numeric element, or in a new window inside an array that
            // ran on from the last one: the numeric loop resumes if the next element is a number.
            _ = try self.consumeNumericArray(
              base: base, to: n, count: count, indices: indices, cursor: &cursor, k: &k,
              state: &state, depth: &depth, containers: &containers, into: &sink
            )
          }
        case .asciiArrayEnd:
          guard depth > 0, !Self.topIsObject(depth: depth, containers: containers) else {
            throw self.error(.unexpectedToken, at: pos)
          }
          try self.record(.endArray, start: pos, length: 1, end: pos &+ 1, base: base, into: &sink)
          depth &-= 1
          state = depth == 0 ? .done : .afterValue
          cursor = pos &+ 1
          k &+= 1
        case .asciiObjectEnd:
          guard Self.topIsObject(depth: depth, containers: containers) else {
            throw self.error(.unexpectedToken, at: pos)
          }
          try self.record(.endObject, start: pos, length: 1, end: pos &+ 1, base: base, into: &sink)
          depth &-= 1
          state = depth == 0 ? .done : .afterValue
          cursor = pos &+ 1
          k &+= 1
        default:
          throw self.error(.unexpectedToken, at: pos)
        }

      case .key, .firstKey:
        switch byte {
        case .asciiQuote:
          guard k &+ 1 < count else { return pos }
          let close = Int(indices[k &+ 1])
          var containsNonASCII = false
          if close > pos &+ 1 {
            let firstBlock = (pos &+ 1 &- windowStart) &>> 6
            let lastBlock = (close &- 1 &- windowStart) &>> 6
            // A key with an escape is buffered and decoded by the dispatcher's key path.
            if Self.windowFlag(needsScan, firstBlock: firstBlock, lastBlock: lastBlock) {
              return pos
            }
            containsNonASCII = Self.windowFlag(
              nonASCII, firstBlock: firstBlock, lastBlock: lastBlock
            )
          }
          try self.validateUTF8IfNeeded(
            base: base, from: pos &+ 1, to: close, containsNonASCII: containsNonASCII,
            reportAt: close
          )
          try self.record(.key, start: pos &+ 1, length: close &- pos &- 1, end: close &+ 1, base: base, into: &sink)
          state = .afterKey
          cursor = close &+ 1
          k &+= 2
        case .asciiObjectEnd:
          guard state == .firstKey, Self.topIsObject(depth: depth, containers: containers)
          else { throw self.error(.unexpectedToken, at: pos) }
          try self.record(.endObject, start: pos, length: 1, end: pos &+ 1, base: base, into: &sink)
          depth &-= 1
          state = depth == 0 ? .done : .afterValue
          cursor = pos &+ 1
          k &+= 1
        default:
          throw self.error(.unexpectedToken, at: pos)
        }

      case .afterKey:
        guard byte == .asciiColon else { throw self.error(.unexpectedToken, at: pos) }
        state = .value
        cursor = pos &+ 1
        k &+= 1

      case .done:
        throw self.error(.trailingContent, at: pos)

      default:
        throw self.error(.unexpectedToken, at: pos)
      }
    }
  }

JSONParserWindow.swift:dispatchOnce.code:
@inlinable
  @inline(__always)
  mutating func dispatchOnce<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    from: Int,
    to n: Int,
    into sink: inout Sink
  ) throws(JSONParsingError) -> Int {
    var i = from
    switch self.state {
    case .value, .firstValue, .afterValue, .key, .firstKey, .afterKey, .done:
      i = try self.consumeStructuralRun(base: base, from: i, to: n, into: &sink)
    case .inString:
      i = try self.consumeStringRun(base: base, from: i, to: n, into: &sink)
    case .inKey:
      i = try self.consumeKeyRun(base: base, from: i, to: n, into: &sink)
    case .escape:
      let byte = base.load(fromByteOffset: i, as: UInt8.self)
      i &+= 1
      try self.consumeEscape(byte, at: i, into: &sink)
    case .unicode:
      let byte = base.load(fromByteOffset: i, as: UInt8.self)
      i &+= 1
      try self.consumeUnicodeDigit(byte, at: i, into: &sink)
    case .number:
      i = try self.consumeNumber(base: base, from: i, to: n, into: &sink)
    case .literal:
      i = try self.consumeLiteral(base: base, from: i, to: n, into: &sink)
    case .skipping, .skippingString, .skippingEscape:
      i = try self.consumeSkipRun(base: base, from: i, to: n, into: &sink)
    }
    return i
  }

JSONParserWindow.swift:parseWindowed.code:
@inlinable
  @inline(never)
  mutating func parseWindowed<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    count n: Int,
    into sink: inout Sink
  ) throws(JSONParsingError) {
    let scratch: UnsafeMutableRawPointer
    if let existing = self.windowScratch {
      scratch = existing
    } else {
      scratch = .allocate(byteCount: Self.windowScratchByteCount, alignment: 8)
      self.windowScratch = scratch
    }
    let indices = scratch.assumingMemoryBound(to: UInt32.self)
    let needsScan = (scratch + Self.windowIndexCapacity &* 4).assumingMemoryBound(to: UInt64.self)
    let nonASCII = needsScan + Self.windowBitmapWordCount

    do throws(JSONParsingError) {
      try self.parseWindows(
        base: base, count: n, indices: indices, needsScan: needsScan, nonASCII: nonASCII,
        into: &sink
      )
    } catch {
      // Commit before the error propagates; a deferring sink's late rejection is earlier in the
      // document than the grammar error and is what gets reported.
      try self.settlePendingStringBegin(base: base, chunkEnd: n, into: &sink)
      try self.commitSink(chunkEnd: n, replacing: error, into: &sink)
    }
    try self.settlePendingStringBegin(base: base, chunkEnd: n, into: &sink)
    try self.commitSink(chunkEnd: n, into: &sink)
    self.consumedByteCount &+= n
  }

JSONParserWindow.swift:parseWindows.code:
@inlinable
  @inline(__always)
  mutating func parseWindows<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    count n: Int,
    indices: UnsafeMutablePointer<UInt32>,
    needsScan: UnsafeMutablePointer<UInt64>,
    nonASCII: UnsafeMutablePointer<UInt64>,
    into sink: inout Sink
  ) throws(JSONParsingError) {
    var i = 0
    if self.pendingUTF8Count > 0 {
      i = try self.completePendingUTF8(base: base, count: n, into: &sink)
    }
    var windowStart = 0
    var windowEnd = 0
    var count = 0
    var entry = 0
    while i < n {
      // A window starts only at a token boundary outside any string, which is what lets the
      // indexer run with no carried state. Anything else — mid-string, a buffered number, an
      // escape in flight — is the dispatcher's, one step at a time until it is back at one.
      guard self.state.isStructural, self.bufferCount == 0 else {
        i = try self.dispatchOnce(base: base, from: i, to: n, into: &sink)
        continue
      }
      if i >= windowEnd {
        // A sparse window is the dispatcher's, stepped until the cursor leaves the span (a step
        // may overrun it, as a long string would), so the sink sees a bulk parse's chunks. Every
        // eighth window is indexed regardless, so a document that turns dense again is noticed.
        if self.windowDensity < Self.sparseWindowDensity,
          self.windowsSinceProbe < Self.windowProbeInterval
        {
          self.windowsSinceProbe &+= 1
          let spanEnd = Swift.min(i &+ Self.windowByteCount, n)
          while i < spanEnd {
            i = try self.dispatchOnce(base: base, from: i, to: n, into: &sink)
          }
          continue
        }
        self.windowsSinceProbe = 0
        let length = Swift.min(Self.windowByteCount, n &- i)
        count = stream_parsing_index_window(
          base.advanced(by: i).assumingMemoryBound(to: UInt8.self), length, UInt32(i),
          indices, needsScan, nonASCII
        )
        self.windowDensity = UInt32(count / ((length &+ 63) &>> 6))
        windowStart = i
        windowEnd = i &+ length
        entry = 0
      } else {
        // Back inside a window the dispatcher took a token out of: the index is still the
        // truth about every position, so the walk resumes at the first entry not yet consumed.
        while entry < count && Int(indices[entry]) < i { entry &+= 1 }
      }
      i = try self.consumeWindow(
        base: base, windowStart: windowStart, windowEnd: windowEnd, to: n, from: i,
        count: count, entry: &entry,
        indices: indices, needsScan: needsScan, nonASCII: nonASCII, into: &sink
      )
      // A cursor short of the window's end is a token the walk handed back — cut by the
      // chunk, or a key with an escape — and it is the dispatcher's, for exactly one step.
      if i < windowEnd {
        i = try self.dispatchOnce(base: base, from: i, to: n, into: &sink)
      }
    }
  }

JSONParserWindow.swift:scanStringValue.code:
@inlinable
  @inline(never)
  mutating func scanStringValue<Sink: StreamParseSink & ~Copyable>(
    base: UnsafeRawPointer,
    from: Int,
    to close: Int,
    into sink: inout Sink
  ) throws(JSONParsingError) -> Int? {
    var i = from
    while i < close {
      let run = streamStringRun(base: base, from: i, to: close)
      if run.end > i {
        try self.validateUTF8IfNeeded(
          base: base, from: i, to: run.end, containsNonASCII: run.containsNonASCII,
          reportAt: nil
        )
        try self.record(.stringChunk, start: i, length: run.end &- i, end: run.end, base: base, into: &sink)
        i = run.end
      }
      guard i < close else { break }
      let byte = base.load(fromByteOffset: i, as: UInt8.self)
      if byte == .asciiBackslash {
        if let fused = try self.fusedEscapeEnd(
          base: base, from: i &+ 1, to: close, coalescing: false, into: &sink
        ) {
          i = fused
          continue
        }
        return i &+ 1
      }
      throw self.error(.unterminatedString, at: i)
    }
    return nil
  }

