      let hash = Self.hash(buffer)
      var vacantBucket = -1
      if let existing = self.slot(forKey: buffer, hash: hash, vacantBucket: &vacantBucket) {
        self.pendingSlot = existing
        self.pendingValue = self.storedValues[Int(existing)]
