@usableFromInline
  func scalarIndex(before index: Int) -> Int {
    var candidate = index &- 1
    var steps = 0
    while steps < 3, candidate > 0, self.utf8Byte(at: candidate) & 0xC0 == 0x80 {
      candidate &-= 1
      steps &+= 1
    }
    return candidate &+ self.decodeScalar(at: candidate).length >= index ? candidate : index &- 1
  }

